  const auto update=[] {return h::handleAdminDefaults(rt::Request("https://ai.ubq.fi/admin/defaults",rt::RequestInit{.method="POST",.headers=rt::Headers{{"Content-Type","application/json"}},.body=R"({"kernel_policy_window_ms":120000})"}));};
