  HarnessScope scope;const auto token="u_"+std::string(64,'4');AWAIT(seeded,h::seedKey(token,"limit-change",100));auto loweredRecord=seeded.record;loweredRecord["usage_limit_requests"]=10;const auto original=h::apiKeyPolicyFromHashRecord(seeded.hash,seeded.record,h::now()),lowered=h::apiKeyPolicyFromHashRecord(seeded.hash,loweredRecord,h::now());ASSERT(original&&lowered);EXPECT_EQ(h::encodeKey(h::apiKeyUsageV3WindowKey(*lowered)),h::encodeKey(h::apiKeyUsageV3WindowKey(*original)));
